#!/usr/bin/env python3
import csv
import json
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

ROOT = Path('/root')

CURRENCY_FIELDS = {
    'reagent_cost_per_1000_tests_usd',
    'network_adjustment_per_run_per_lab_usd',
    'shipper_cost_usd',
    'base_payment_per_run_per_lab_usd',
    'total_payment_per_run_per_lab_usd',
    'annual_reagent_cost_14_day_usd',
    'annual_reagent_cost_28_day_usd',
    'annual_shipper_cost_14_day_usd',
    'annual_shipper_cost_28_day_usd',
    'annual_revenue_14_day_usd',
    'annual_revenue_28_day_usd',
    'annual_margin_14_day_usd',
    'annual_margin_28_day_usd',
    'annual_margin_difference_28_minus_14_usd',
    'total_annual_margin_14_day_usd',
    'total_annual_margin_28_day_usd',
    'total_annual_margin_difference_28_minus_14_usd',
    'absolute_total_margin_difference_usd',
}

class RawNumber:
    def __init__(self, text):
        self.text = text


def money(value):
    """Return a RawNumber JSON numeric literal rounded/formatted to exactly 2 decimals."""
    if not isinstance(value, Decimal):
        value = Decimal(str(value))
    return RawNumber(format(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f'))


def D(value):
    return Decimal(str(value))


def dump_json_exact(obj, indent=2):
    """Minimal pretty JSON writer that supports RawNumber literals."""
    def write(value, level):
        sp = ' ' * (indent * level)
        child_sp = ' ' * (indent * (level + 1))
        if isinstance(value, RawNumber):
            return value.text
        if isinstance(value, dict):
            if not value:
                return '{}'
            parts = []
            for k, v in value.items():
                parts.append(f'{child_sp}{json.dumps(k)}: {write(v, level + 1)}')
            return '{\n' + ',\n'.join(parts) + '\n' + sp + '}'
        if isinstance(value, list):
            if not value:
                return '[]'
            parts = [f'{child_sp}{write(item, level + 1)}' for item in value]
            return '[\n' + ',\n'.join(parts) + '\n' + sp + ']'
        return json.dumps(value)
    return write(obj, 0)


def read_csv(name):
    with (ROOT / name).open(newline='') as f:
        return list(csv.DictReader(f))


def main():
    manifest = json.loads((ROOT / 'panel_manifest.json').read_text())
    holdouts = json.loads((ROOT / 'holdouts.json').read_text())
    template = json.loads((ROOT / 'report_template.json').read_text())
    contract_rows = read_csv('contract_terms.csv')
    network_rows = read_csv('network_adjustments.csv')
    override_rows = read_csv('lab_capacity_overrides.csv')
    shipper_rows = read_csv('shipper_cost.csv')

    exclude_codes = {
        row['panel_code']
        for row in holdouts.get('holdouts', [])
        if row.get('holdout_state') == 'exclude'
    }

    retained = []
    for cluster in manifest.get('service_clusters', []):
        for panel in cluster.get('panels', []):
            if panel.get('analysis_mode') == 'review' and panel.get('panel_code') not in exclude_codes:
                retained.append(panel)

    retained_by_code = {p['panel_code']: p for p in retained}

    # Resolve current contract by panel_name or alias_labels; latest effective_week wins.
    contract_by_code = {}
    for row in contract_rows:
        if row.get('status_flag') != 'current':
            continue
        matched_code = None
        panel_ref = row.get('panel_ref')
        for panel in retained:
            if panel_ref == panel.get('panel_name') or panel_ref in panel.get('alias_labels', []):
                matched_code = panel['panel_code']
                break
        if matched_code is None:
            continue
        prev = contract_by_code.get(matched_code)
        if prev is None or row.get('effective_week', '') > prev.get('effective_week', ''):
            contract_by_code[matched_code] = row

    network_adjustment = {
        row['network_tier']: D(row['network_adjustment_per_run_per_lab_usd'])
        for row in network_rows
    }
    shipper_cost = {
        row['shipper_class']: D(row['shipper_cost_usd'])
        for row in shipper_rows
    }

    valid_overrides = {}
    for row in override_rows:
        if row.get('approval') != 'approved':
            continue
        if row.get('rev', '').strip() == '' or row.get('active_labs', '').strip() == '':
            continue
        code = row['panel_code']
        if code not in retained_by_code:
            continue
        rev = D(row['rev'])
        current = valid_overrides.get(code)
        if current is None or rev > current['rev']:
            valid_overrides[code] = {'rev': rev, 'active_labs': int(row['active_labs'])}

    panels = []
    total_margin_14 = Decimal('0')
    total_margin_28 = Decimal('0')
    runs14 = Decimal('26')
    runs28 = Decimal('13')

    for panel in retained:
        code = panel['panel_code']
        contract = contract_by_code.get(code)
        if contract is None:
            raise ValueError(f'No current contract found for retained panel {code}')
        base_payment = D(contract['base_payment_per_run_per_lab_usd'])
        adjustment = network_adjustment.get(panel['network_tier'], Decimal('0.0'))
        active_labs = valid_overrides.get(code, {}).get('active_labs', int(panel['default_active_labs']))
        ship_cost = shipper_cost[panel['shipper_class']]
        reagent = D(panel['reagent_cost_per_1000_tests_usd'])
        tests14 = D(panel['tests_per_lab_per_run_14_day'])
        tests28 = D(panel['tests_per_lab_per_run_28_day'])
        labs = D(active_labs)
        total_payment = base_payment + adjustment

        annual_revenue_14 = total_payment * labs * runs14
        annual_reagent_cost_14 = reagent * labs * tests14 * runs14 / Decimal('1000')
        annual_shipper_cost_14 = ship_cost * runs14
        annual_margin_14 = annual_revenue_14 - annual_reagent_cost_14 - annual_shipper_cost_14

        annual_revenue_28 = total_payment * labs * runs28
        annual_reagent_cost_28 = reagent * labs * tests28 * runs28 / Decimal('1000')
        annual_shipper_cost_28 = ship_cost * runs28
        annual_margin_28 = annual_revenue_28 - annual_reagent_cost_28 - annual_shipper_cost_28
        difference = annual_margin_28 - annual_margin_14

        total_margin_14 += annual_margin_14
        total_margin_28 += annual_margin_28

        panels.append({
            'panel_code': code,
            'panel_name': panel['panel_name'],
            'active_labs': active_labs,
            'reagent_cost_per_1000_tests_usd': money(reagent),
            'network_tier': panel['network_tier'],
            'network_adjustment_per_run_per_lab_usd': money(adjustment),
            'shipper_class': panel['shipper_class'],
            'shipper_cost_usd': money(ship_cost),
            'base_payment_per_run_per_lab_usd': money(base_payment),
            'total_payment_per_run_per_lab_usd': money(total_payment),
            'tests_per_lab_per_run_14_day': int(panel['tests_per_lab_per_run_14_day']),
            'tests_per_lab_per_run_28_day': int(panel['tests_per_lab_per_run_28_day']),
            'annual_reagent_cost_14_day_usd': money(annual_reagent_cost_14),
            'annual_reagent_cost_28_day_usd': money(annual_reagent_cost_28),
            'annual_shipper_cost_14_day_usd': money(annual_shipper_cost_14),
            'annual_shipper_cost_28_day_usd': money(annual_shipper_cost_28),
            'annual_revenue_14_day_usd': money(annual_revenue_14),
            'annual_revenue_28_day_usd': money(annual_revenue_28),
            'annual_margin_14_day_usd': money(annual_margin_14),
            'annual_margin_28_day_usd': money(annual_margin_28),
            'annual_margin_difference_28_minus_14_usd': money(difference),
        })

    panels.sort(key=lambda p: p['panel_code'])
    total_difference = total_margin_28 - total_margin_14
    absolute_difference = abs(total_difference)
    threshold = Decimal('6000')
    decision = 'adopt_28_day' if absolute_difference < threshold else 'keep_14_day'
    justification = (
        f'{decision} because the absolute total margin difference '
        f'${absolute_difference.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP):.2f} '
        f'is {"below" if absolute_difference < threshold else "at or above"} the $6000.00 threshold.'
    )

    report = {
        'metadata': template['metadata'],
        'audit_notes': template['audit_notes'],
        'analysis': {
            'assumptions': {
                'runs_per_year_14_day': 26,
                'runs_per_year_28_day': 13,
                'switch_threshold_usd': 6000,
                'override_rule': 'highest numeric approved rev with non-empty active_labs, else default_active_labs',
                'holdout_rule': 'exclude holdout_state=exclude',
                'adjustment_rule': 'missing network_tier adjustment defaults to 0.0',
            },
            'panels': panels,
            'totals': {
                'total_annual_margin_14_day_usd': money(total_margin_14),
                'total_annual_margin_28_day_usd': money(total_margin_28),
                'total_annual_margin_difference_28_minus_14_usd': money(total_difference),
                'absolute_total_margin_difference_usd': money(absolute_difference),
            },
            'recommendation': {
                'decision': decision,
                'justification': justification,
            },
        },
    }

    (ROOT / 'diagpanel_policy_report.json').write_text(dump_json_exact(report, indent=2) + '\n')
    summary_lines = [
        f'Total 14-day margin (USD): {total_margin_14.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP):.2f}',
        f'Total 28-day margin (USD): {total_margin_28.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP):.2f}',
        f'Absolute difference (USD): {absolute_difference.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP):.2f}',
        f'Final decision: {decision}',
    ]
    (ROOT / 'diagpanel_policy_summary.md').write_text('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
